ruleBookInfo.intro:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var el = doc.select('#text').first();
var t = el != null ? el.text() : '';
var a1 = t.indexOf('简介：');
var a2 = t.indexOf('文案：');
var a = a1 >= 0 && (a2 < 0 || a1 < a2) ? a1 : a2;
var b = t.indexOf('第1章');
var r = (a >= 0 && b > a) ? t.substring(a + 3, b).trim() : '';
r.split(' 　　').join('\n');

ruleContent.content:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var el = doc.select('#text').first();
var html = el != null ? el.html() : '';
var i = html.indexOf('<p>第');          // ① 从本章标记开始（切掉《书名》作者：+简介整段）
if (i >= 0) { html = html.substring(i); }
var k = html.indexOf('id="goto-pl"');   // ② 截断页脚噪音（评论/JS/推荐/分页导航）
if (k >= 0) { html = html.substring(0, k); }
var j = html.indexOf('耽美小说');       // ③ 删章末水印
if (j >= 0) { html = html.substring(0, j); }
html;

