ruleToc.chapterList:
@js:
var url = baseUrl;
var prefix = url.substring(0, url.lastIndexOf('/') + 1);
var bid = url.substring(url.lastIndexOf('/') + 1, url.length - 5);
var b = java.ajax(url);
var i = b.indexOf('<b>');
var j = i >= 0 ? b.indexOf('</b>', i) : -1;
var total = (i >= 0 && j > i) ? parseInt(b.substring(i + 3, j)) : 1;
var list = [];
for (var k = 0; k < total; k++) {
  list.push(JSON.stringify({title: '第' + (k + 1) + '页', url: k == 0 ? url : prefix + bid + '_' + k + '.html'}));
}
list;

