function sign(list){
var sb='';
sb+="Fb0gqLMSf5Android";
list=list.sort();
i=0;
while(i<list.length){
if(i==0){
sb+=list[i]
}else{
    if(list[i].match(/lang-app=/)){  
      i2=i+1;
